INSERT INTO price_report (pharmacy_id, drug_id, price, purchased_at, source, status, flagged)
SELECT p.id, d.id, src.price, src.purchased_at, src.source, src.status, src.flagged
FROM src
JOIN pharmacy p ON p.hira_code = src.hira_code
JOIN drug d ON d.item_seq = src.item_seq;

