INSERT INTO price_report (pharmacy_id, drug_id, price, purchased_at, source, status, flagged)
SELECT p.id, d.id, src.price, src.purchased_at, src.source, src.status, src.flagged
FROM src
JOIN pharmacy p ON p.hira_code = src.hira_code
JOIN drug d ON d.item_seq = src.item_seq;


-- pharmacy_drug_price_stat 초기 계산 (docs/DATABASE.md §5.2, docs/ROADMAP.md T-10과 동일 로직).
-- 1차: 최근 90일 창. 2차: 90일 창에 유효 제보가 없는 조합만 180일 창으로 확대.
WITH valid_90 AS (
    SELECT pharmacy_id, drug_id, price, purchased_at
    FROM price_report
    WHERE status = 'ACTIVE' AND flagged = false
      AND purchased_at >= CURRENT_DATE - 90
),
q_90 AS (
    -- percentile_cont(ordered-set aggregate)는 OVER() 윈도우로 못 쓴다 (PostgreSQL
    -- 제약). (pharmacy_id, drug_id)별 GROUP BY 집계로 구한 뒤 join으로 되돌린다.
    SELECT pharmacy_id, drug_id,
           percentile_cont(0.25) WITHIN GROUP (ORDER BY price) AS q1,
           percentile_cont(0.75) WITHIN GROUP (ORDER BY price) AS q3,
           count(*) AS n
    FROM valid_90
    GROUP BY pharmacy_id, drug_id
),
trimmed_90 AS (
    SELECT v.pharmacy_id, v.drug_id, v.price, v.purchased_at
    FROM valid_90 v
    JOIN q_90 q ON q.pharmacy_id = v.pharmacy_id AND q.drug_id = v.drug_id
    WHERE q.n < 4 OR v.price BETWEEN q.q1 - 1.5 * (q.q3 - q.q1) AND q.q3 + 1.5 * (q.q3 - q.q1)
)
INSERT INTO pharmacy_drug_price_stat
    (pharmacy_id, drug_id, rep_price, min_price, max_price, avg_price, report_count, last_reported_at, window_days, calculated_at)
SELECT
    t.pharmacy_id, t.drug_id,
    percentile_cont(0.5) WITHIN GROUP (ORDER BY t.price)::int,
    MIN(t.price)::int, MAX(t.price)::int, AVG(t.price)::int, COUNT(*)::int,
    MAX(t.purchased_at), 90, now()
FROM trimmed_90 t
GROUP BY t.pharmacy_id, t.drug_id
ON CONFLICT (pharmacy_id, drug_id) DO NOTHING;

-- 2차: 90일 창에서 못 채운 조합을 180일 창으로 재시도
WITH covered AS (
    SELECT pharmacy_id, drug_id FROM pharmacy_drug_price_stat
),
valid_180 AS (
    SELECT pr.pharmacy_id, pr.drug_id, pr.price, pr.purchased_at
    FROM price_report pr
    WHERE pr.status = 'ACTIVE' AND pr.flagged = false
      AND pr.purchased_at >= CURRENT_DATE - 180
      AND NOT EXISTS (
          SELECT 1 FROM covered c
          WHERE c.pharmacy_id = pr.pharmacy_id AND c.drug_id = pr.drug_id
      )
),
q_180 AS (
    SELECT pharmacy_id, drug_id,
           percentile_cont(0.25) WITHIN GROUP (ORDER BY price) AS q1,
           percentile_cont(0.75) WITHIN GROUP (ORDER BY price) AS q3,
           count(*) AS n
    FROM valid_180
    GROUP BY pharmacy_id, drug_id
),
trimmed_180 AS (
    SELECT v.pharmacy_id, v.drug_id, v.price, v.purchased_at
    FROM valid_180 v
    JOIN q_180 q ON q.pharmacy_id = v.pharmacy_id AND q.drug_id = v.drug_id
    WHERE q.n < 4 OR v.price BETWEEN q.q1 - 1.5 * (q.q3 - q.q1) AND q.q3 + 1.5 * (q.q3 - q.q1)
)
INSERT INTO pharmacy_drug_price_stat
    (pharmacy_id, drug_id, rep_price, min_price, max_price, avg_price, report_count, last_reported_at, window_days, calculated_at)
SELECT
    t.pharmacy_id, t.drug_id,
    percentile_cont(0.5) WITHIN GROUP (ORDER BY t.price)::int,
    MIN(t.price)::int, MAX(t.price)::int, AVG(t.price)::int, COUNT(*)::int,
    MAX(t.purchased_at), 180, now()
FROM trimmed_180 t
GROUP BY t.pharmacy_id, t.drug_id
ON CONFLICT (pharmacy_id, drug_id) DO NOTHING;
